            ],
        };

        const modelKeys = keys[type] || [];
        return modelKeys.map(key => ({
            label: this.app.configuration.getUiText(key) ?? ""
        }));
    }

    public async processModelActions(modelType: ModelType) {
        let modelActions: vscode.QuickPickItem[] = this.getActions(modelType);
        let actionSelected = await vscode.window.showQuickPick(modelActions);
        if (actionSelected) {
            await this.processActions(modelType, actionSelected);
        }
    }

    async processActions(type: ModelType, selected: vscode.QuickPickItem): Promise<void> {
        const details = this.getTypeDetails(type);
        const actionMap = this.getActionMap(type);
        const action = Object.keys(actionMap).find(key => selected.label === actionMap[key]);
        if (!action) return;

        switch (action) {
            case 'select':
                await this.selectModel(type, details.modelsList);
                break;
            case 'deselect':
                await this.deselectModel(type, details);
                break;
            case 'addLocal':
                await this.addModel(type, 'local');
                break;
            case 'addExternal':
                await this.addModel(type, 'external');
                break;
            case 'addHf':
                await this.addModel(type, 'hf');
                break;
            case 'addOaiComp':
                await this.addModel(type, 'oaiComp');
                break;
            case 'delete':
                await this.deleteModel(details.modelsList, details.modelsListSettingName);
                break;
            case 'view':
                await this.viewModel(type, details.modelsList);
                break;
            case 'export':
                await this.exportModel(type, details.modelsList);
                break;
            case 'import':
                await this.importModel(details.modelsList, details.modelsListSettingName);
                break;
        }
    }

    private getActionMap(type: ModelType): Record<string, string> {
        const typeStr = type.charAt(0).toUpperCase() + type.slice(1);
        return {
            select: this.app.configuration.getUiText(UI_TEXT_KEYS[`selectStart${typeStr}Model` as keyof typeof UI_TEXT_KEYS]) ?? "",
            deselect: this.app.configuration.getUiText(UI_TEXT_KEYS[`deselectStop${typeStr}Model` as keyof typeof UI_TEXT_KEYS]) ?? "",
            addLocal: this.app.configuration.getUiText(UI_TEXT_KEYS[`addLocal${typeStr}Model` as keyof typeof UI_TEXT_KEYS]) ?? "",
            addExternal: this.app.configuration.getUiText(UI_TEXT_KEYS[`addExternal${typeStr}Model` as keyof typeof UI_TEXT_KEYS]) ?? "",
            addHf: this.app.configuration.getUiText(UI_TEXT_KEYS[`add${typeStr}ModelFromHuggingface` as keyof typeof UI_TEXT_KEYS]) ?? "",
            addOaiComp: this.app.configuration.getUiText(UI_TEXT_KEYS[`add${typeStr}OpenAiCompModel` as keyof typeof UI_TEXT_KEYS]) ?? "",
            view: this.app.configuration.getUiText(UI_TEXT_KEYS[`view${typeStr}ModelDetails` as keyof typeof UI_TEXT_KEYS]) ?? "",
            delete: this.app.configuration.getUiText(UI_TEXT_KEYS[`delete${typeStr}Model` as keyof typeof UI_TEXT_KEYS]) ?? "",
            export: this.app.configuration.getUiText(UI_TEXT_KEYS[`export${typeStr}Model` as keyof typeof UI_TEXT_KEYS]) ?? "",
            import: this.app.configuration.getUiText(UI_TEXT_KEYS[`import${typeStr}Model` as keyof typeof UI_TEXT_KEYS]) ?? "",
        };
    }

    selectModel = async (type: ModelType, modelsList: LlmModel[], shoudStartModel:boolean = true): Promise<LlmModel | undefined> => {
        const details = this.getTypeDetails(type);
        let allModels = modelsList.concat(PREDEFINED_LISTS.get(type) as LlmModel[])
        let modelsItems: QuickPickItem[] = this.getModels(modelsList, "", true);
        modelsItems = modelsItems.concat(this.getModels(PREDEFINED_LISTS.get(type) as LlmModel[], "(predefined) ", true, modelsList.length));
        modelsItems.push({ label: (modelsItems.length + 1) + ". Use settings", description: "" });

        const selectedModelItem = await vscode.window.showQuickPick(modelsItems);
        if (selectedModelItem) {
            const launchToEndpoint = new Map([
                ["launch_completion", "endpoint"],
                ["launch_chat", "endpoint_chat"],
                ["launch_embeddings", "endpoint_embeddings"],
                ["launch_tools", "endpoint_tools"]
            ]);
            let model: LlmModel;
            if (parseInt(selectedModelItem.label.split(". ")[0], 10) == modelsItems.length) {
                // Use settings
                const aiModel = this.app.configuration.ai_model;
                const endpoint = this.app.configuration[launchToEndpoint.get(details.launchSettingName) as keyof Configuration] as string;
                const localStartCommand = this.app.configuration[details.launchSettingName as keyof Configuration] as string
                model = {
                    name: "Use settings",
                    aiModel: aiModel,
                    isKeyRequired: false,
                    endpoint: endpoint,
                    localStartCommand: localStartCommand
                };
            } else {
                const index = parseInt(selectedModelItem.label.split(". ")[0], 10) - 1;
                model = allModels[index];
            }

            if (shoudStartModel) await this.selectStartModel(model, type, details);

            return model;
        }
        return undefined
    }

    getAllToolsModelsList = (): LlmModel[] => {
        return this.app.configuration.tools_models_list
                .concat((PREDEFINED_LISTS.get(ModelType.Tools) as LlmModel[]))
    }

    getAllChatModelsList = (): LlmModel[] => {
        return this.app.configuration.chat_models_list
                .concat((PREDEFINED_LISTS.get(ModelType.Chat) as LlmModel[]))
    }

    getAllComplModelsList = (): LlmModel[] => {
        return this.app.configuration.completion_models_list
                .concat((PREDEFINED_LISTS.get(ModelType.Completion) as LlmModel[]))
    }

    getAllEmbsModelsList = (): LlmModel[] => {
        return this.app.configuration.embeddings_models_list
                .concat((PREDEFINED_LISTS.get(ModelType.Embeddings) as LlmModel[]))
    }


    selectDefaultModel = async (modelType: ModelType, persistenceKey: string) => {
        const defaultModel = this.app.persistence.getGlobalValue(persistenceKey);
        if (defaultModel) {
            await this.selectStartModel(defaultModel, modelType, this.getTypeDetails(modelType));
        }
        this.app.llamaWebviewProvider.updateLlamaView();
    }

    public async selectStartModel(model: LlmModel, type: ModelType, details: ModelTypeDetails) {
        await this.addApiKey(model);

        await details.killCmd();
        if (model.localStartCommand && this.app.configuration.only_one_local_model) await this.deselectAllLocalModels();
        if (model.localStartCommand) await details.shellCmd(this.sanitizeCommand(model.localStartCommand ?? ""));
        await this.app.persistence.setValue(this.getSelectedProp(type), model);
        if (type === ModelType.Tools) {
            this.app.llamaChatModelProvider.notifyModelsChanged();
        }
        if (type == ModelType.Tools && model?.isKeyRequired !== undefined && model.isKeyRequired){
            const apiKey = [REDACTED]"");
            if (apiKey){
                this.app.configuration.axiosRequestConfigTools = {
                    headers: {
                        Authorization: `Bearer ${apiKey}`,
                        "Content-Type": "application/json",
                    },
                }
            }
        }

        this.app.setSelectedModel(type, model);
    }

    private deselectAllLocalModels = async () => {
        // Deselects models for completion, chat, tools if they are local
        const complModel = this.app.getComplModel()
        if (complModel && complModel.localStartCommand) await this.deselectAndClearModel(ModelType.Completion);
        const chatModel = this.app.getChatModel()
        if (chatModel && chatModel.localStartCommand) await this.deselectAndClearModel(ModelType.Chat);
        const toolsModel = this.app.getToolsModel()
        if (toolsModel && toolsModel.localStartCommand) await this.deselectAndClearModel(ModelType.Tools);
    }

    public async addModel(type: ModelType, kind: 'local' | 'external' | 'hf' | 'oaiComp'): Promise<void> {
        const details = this.getTypeDetails(type);
        const strategy = this.strategies[kind];
        if (strategy) {
            await strategy.add(details);
        }
    }

    async deleteModel(modelsList: LlmModel[], settingName: string): Promise<void> {
        const modelsItems: QuickPickItem[] = this.getModels(modelsList, "", false);
        const modelItem = await vscode.window.showQuickPick(modelsItems);
        if (modelItem) {
            let modelIndex = parseInt(modelItem.label.split(". ")[0], 10) - 1;
            const shouldDeleteModel = await this.app.dialogs.confirmAction("Are you sure you want to delete the model below?",
                this.getDetails(modelsList[modelIndex])
            );
            if (shouldDeleteModel) {
                this.deleteModelByIndex(modelsList, modelIndex, settingName);
            }
        }
    }

    deleteModelByIndex = (modelsList: LlmModel[], modelIndex: number, settingName: string) => {
        modelsList.splice(modelIndex, 1);
        this.app.configuration.updateConfigValue(settingName, modelsList);
        vscode.window.showInformationMessage("The model is deleted.");
    }

    public async viewModel(type: ModelType , modelsList: LlmModel[]): Promise<void> {
        let allModels = modelsList.concat(PREDEFINED_LISTS.get(type) as LlmModel[])
        let modelsItems: QuickPickItem[] = this.getModels(modelsList, "", false);
        modelsItems = modelsItems.concat(this.getModels(PREDEFINED_LISTS.get(type) as LlmModel[], "(predefined) ", false, modelsList.length));
        let modelItem = await vscode.window.showQuickPick(modelsItems);
        if (modelItem) {
            let modelIndex = parseInt(modelItem.label.split(". ")[0], 10) - 1;
            let selectedModel = allModels[modelIndex];
            await this.showModelDetails(selectedModel);
        }
    }

    public async showModelDetails(model: LlmModel): Promise<void> {
        await this.app.dialogs.showOkDialog("Model details: \n\n" + this.getDetails(model));
    }

    public async addPersistModel(newModel: LlmModel, details: ModelTypeDetails){
        ServiceUtils.addPersistModel(newModel, details, this.app);
    }

    async exportModel(type: ModelType, modelsList: LlmModel[]): Promise<void> {
        let allModels = modelsList.concat(PREDEFINED_LISTS.get(type) as LlmModel[])
        let modelsItems: QuickPickItem[] = this.getModels(modelsList, "", false);
        modelsItems = modelsItems.concat(this.getModels(PREDEFINED_LISTS.get(type) as LlmModel[], "(predefined) ", false, modelsList.length));
        let modelItem = await vscode.window.showQuickPick(modelsItems);
        if (modelItem) {
            let modelIndex = parseInt(modelItem.label.split(". ")[0], 10) - 1;
            let selectedModel = allModels[modelIndex];
            let shouldExport = await this.app.dialogs.showYesNoDialog("Do you want to export the following model? \n\n" +
                this.getDetails(selectedModel)
            );

            if (shouldExport) {
                const uri = await vscode.window.showSaveDialog({
                    defaultUri: vscode.Uri.file(path.join(vscode.workspace.rootPath || '', selectedModel.name + '.json')),
                    filters: {
                        'Model Files': ['json'],
                        'All Files': ['*']
                    },
                    saveLabel: 'Export Model'
                });

                if (uri) {
                    const jsonContent = JSON.stringify(selectedModel, null, 2);
                    fs.writeFileSync(uri.fsPath, jsonContent, 'utf8');
                    vscode.window.showInformationMessage("Model is saved.")
                }
            }
        }
    }

    async importModel(modelList: LlmModel[], settingName: string): Promise<void> {
        const uris = await vscode.window.showOpenDialog({
            canSelectMany: false,
            openLabel: 'Import Model',
            filters: {
                'Model Files': ['json'],
                'All Files': ['*']
            },
        });

        if (!uris || uris.length === 0) {
            return;
        }

        const filePath = uris[0].fsPath;

        const fileContent = fs.readFileSync(filePath, 'utf8');
        const newModel = JSON.parse(fileContent);
        // Sanitize imported model
        if (newModel.name) newModel.name = this.sanitizeInput(newModel.name);
        if (newModel.localStartCommand) newModel.localStartCommand = this.sanitizeCommand(newModel.localStartCommand);
        if (newModel.endpoint) newModel.endpoint = this.sanitizeInput(newModel.endpoint);
        if (newModel.aiModel) newModel.aiModel = this.sanitizeInput(newModel.aiModel);

        const modelDetails = this.getDetails(newModel);
        const shouldAddModel = await this.app.dialogs.confirmAction("A new model will be added. Do you want to add the model?", modelDetails);

        if (shouldAddModel) {
            modelList.push(newModel);
            this.app.configuration.updateConfigValue(settingName, modelList);
            vscode.window.showInformationMessage("The model is added.");
        }
        vscode.window.showInformationMessage("Model imported: " + newModel.name);
    }

    public async deselectModel(type: ModelType, details: ModelTypeDetails): Promise<void> {
        await details.killCmd();
        this.clearModel(type);
    }

    getDetails(model: LlmModel): string {
        return "name: " + model.name +
            "\nlocal start command: " + model.localStartCommand +
            "\nendpoint: " + model.endpoint +
            "\nmodel name for provider: " + model.aiModel +
            "\napi key required: " + model.isKeyRequired;
    }

    private getModels(models: LlmModel[], prefix: string, hasDetails: boolean, lastModelNumber: number = 0): QuickPickItem[] {
        const modelsItems: QuickPickItem[] = [];
        let i = lastModelNumber;
        for (let model of models) {
            i++;
            if (hasDetails) {
                modelsItems.push({
                    label: i + ". " + prefix + model.name,
                    description: model.localStartCommand,
                    detail: "Selects the model " + (model.localStartCommand ? ", downloads the model (if not yet done) and starts a llama serve with it." : model.name)
                });
            } else {
                modelsItems.push({
                    label: i + ". " + prefix + model.name,
                    description: model.localStartCommand??model.name
                })
            }
        }
        return modelsItems;
    }

    public getTypeDetails(type: ModelType): ModelTypeDetails {
        const config = MODEL_TYPE_CONFIG[type];
        return {
            modelType: type,
            modelsList: (this.app.configuration as any)[config.settingName],
            modelsListSettingName: config.settingName,
            newModelPort: (this.app.configuration as any)[config.portSetting],
            newModelHost: (this.app.configuration as any)[config.hostSetting],
            selModelPropName: config.propName,
            launchSettingName: config.launchSetting,
            killCmd: (this.app.llamaServer as any)[config.killCmdName],
            shellCmd: (this.app.llamaServer as any)[config.shellCmdName]
        };
    }

    private getSelectedProp(type: ModelType): string {
        const propMap = {
            [ModelType.Completion]: MODEL_TYPE_CONFIG[ModelType.Completion].propName,
            [ModelType.Chat]: MODEL_TYPE_CONFIG[ModelType.Chat].propName,
            [ModelType.Embeddings]: MODEL_TYPE_CONFIG[ModelType.Embeddings].propName,
            [ModelType.Tools]: MODEL_TYPE_CONFIG[ModelType.Tools].propName
        };
        return propMap[type] || '';
    }

    public async addApiKey(model: LlmModel): Promise<void> {
        if (model.isKeyRequired) {
            const apiKey = [REDACTED] ?? "");
            if (!apiKey) {
                let result = await vscode.window.showInputBox({
                    placeHolder: 'Enter your api key for ' + model.endpoint,
                    prompt: 'your api key for ' + model.endpoint,
                    value: ''
                });
                result = this.sanitizeInput(result || '');
                if (result) {
                    this.app.persistence.setApiKey(model.endpoint ?? "", result);
                    vscode.window.showInformationMessage("Your API key for " + model.endpoint + " was saved.")
                }
            }
        }
    }

    sanitizeCommand = (command: string): string => {
        if (!command) return '';
        // TODO Consider escaping some chars: return command.trim().replace(/[`#$\<>\?\\|!{}()[\]^"]/g, '\\$&');
        return command.trim();
    }

    public sanitizeInput(input: string): string {
        return input ? input.trim() : '';
    }

    clearModel = (type: ModelType) => {
        this.app.setSelectedModel(type, Application.emptyModel);
        this.app.setModelState(type, "");
        this.app.llamaWebviewProvider.updateLlamaView();
    }

    public async deselectAndClearModel(modelType: ModelType) {
        await this.deselectModel(modelType, this.getTypeDetails(modelType));
        this.clearModel(modelType);
        this.app.llamaWebviewProvider.updateLlamaView();
    }  

    public async selectAndSetModel(modelType: ModelType, modelsList: LlmModel[]) {
        let model = await this.app.modelService.selectModel(modelType, modelsList);
        this.app.setSelectedModel(modelType, model);
    }

    public async selectAgentModel(modelType: ModelType, modelsList: LlmModel[]) {
        let model = await this.app.modelService.selectModel(modelType, modelsList, false);
        this.app.setAgentModel(model);
    }

    public getEmptyModel(): LlmModel {
        return Application.emptyModel
    }

    public async checkForToolsModel() {
        let toolsModel = this.app.getToolsModel();
        let targetUrl = this.app.configuration.endpoint_tools ? this.app.configuration.endpoint_tools + "/" : "";
        if (!toolsModel || !toolsModel.name) {
            await this.app.modelService.selectDefaultModel(ModelType.Tools, PERSISTENCE_KEYS.DEFAULT_TOOLS_MODEL);
            toolsModel = this.app.getToolsModel();
        }
        if (toolsModel && toolsModel.endpoint) {
            const toolsEndpoint = Utils.trimTrailingSlash(toolsModel.endpoint);
            targetUrl = toolsEndpoint ? toolsEndpoint + "/" : "";
        }
        if (!targetUrl) {
            await this.app.dialogs.suggestModelSelection(
                "Select a tools model or an env with tools model to use Llama Agent.",
                "After the tools model is loaded, try again opening llama agent.",
                "No endpoint for the tools model. Select an env with tools model or enter the endpoint of a running llama.cpp server with tools model in setting endpoint_tools.",
                this.app
            );

            return false;
        }
        else return true;
    }

    periodicModelHealthUpdate = async () => {
        if (this.app.configuration.health_check_interval_s > 0) {
            if (this.app.configuration.health_check_compl_enabled  && this.app.isComplModelSelected()) {
                await this.updateModelState(ModelType.Completion);
            }
            if (this.app.configuration.health_check_chat_enabled  && this.app.isChatModelSelected()) {
                await this.updateModelState(ModelType.Chat);
            }
            if (this.app.configuration.health_check_embs_enabled  && this.app.isEmbeddingsModelSelected()) {
                await this.updateModelState(ModelType.Embeddings);
            }
            if (this.app.configuration.health_check_tools_enabled  && this.app.isToolsModelSelected()) {
                await this.updateModelState(ModelType.Tools);
            }
        }
    }

    public async checkModelHealth(modelType: ModelType) {
        let healthState = await this.app.llamaServer.checkHealth(modelType, this.app.getModel(modelType));
        if (healthState.toLowerCase() == "ok" || healthState.toLowerCase() == "healthy") vscode.window.showInformationMessage(modelType.charAt(0).toUpperCase() + modelType.slice(1) + " model health is OK.");
        else vscode.window.showErrorMessage("Error with " + modelType + " model:" + healthState);
        this.app.setModelState(modelType, healthState);
    }

    private async updateModelState(modelType: ModelType) {
        let healthState = await this.app.llamaServer.checkHealth(modelType, this.app.getModel(modelType));
        let currentHealthState = this.app.getModelState(modelType);
        if ((currentHealthState == "" || currentHealthState.toLocaleLowerCase() == "ok" || currentHealthState.toLocaleLowerCase() == "healthy") 
            && healthState.toLowerCase() != "ok" && healthState.toLowerCase() != "healthy") {
            vscode.window.showErrorMessage("Error with completion model:" + healthState);
        }
        this.app.setModelState(modelType, healthState.slice(0, 150));
    }
}

import { Application } from "../application";
import vscode, { QuickPickItem } from "vscode";
import { Agent, AgentCommand } from "../types";
import { Utils } from "../utils";
import * as fs from 'fs';
import * as path from 'path';
import { AGENT_COMMAND, PREDEFINED_LISTS_KEYS, SETTING_NAME_FOR_LIST, UI_TEXT_KEYS } from "../constants";
import { PREDEFINED_LISTS } from "../lists";

export class AgentCommandService {
    private app: Application;

    constructor(app: Application) {
        this.app = app;
    }

    public getAgentCommandsActions(): vscode.QuickPickItem[] {
        return [
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.addAgentCommand) ?? ""
            },
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.viewAgentCommandDetails) ?? ""
            },
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.editAgentCommandDetails) ?? ""
            },
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.deleteAgentCommand) ?? ""
            },
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.exportAgentCommand) ?? ""
            },
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.importAgentCommand) ?? ""
            },
        ];
    }

    removePreffix = (agentCommandName: string): string => {
        let strippedCommand = agentCommandName;
        // Strip the periodic-execution marker (⏰) if present - it is added
        // by getAgentCommandsList to visually mark scheduled commands.
        if (strippedCommand.startsWith("⏰ ")) {
            strippedCommand = strippedCommand.slice(2);
        }
        if (strippedCommand.startsWith(`[${AGENT_COMMAND.type_preffix_script}]`)) {
            strippedCommand = strippedCommand.slice(`[${AGENT_COMMAND.type_preffix_script}]`.length);
        } else if (strippedCommand.startsWith(`[${AGENT_COMMAND.type_preffix_prompt}]`)) {
            strippedCommand = strippedCommand.slice(`[${AGENT_COMMAND.type_preffix_prompt}]`.length);
        }

        return strippedCommand;
    }

    async processActions(selected: QuickPickItem): Promise<void> {
        const label = selected.label;
        try {
            switch (label) {
                case this.app.configuration.getUiText(UI_TEXT_KEYS.addAgentCommand):
                    await this.addAgentCommand();
                    break;
                case this.app.configuration.getUiText(UI_TEXT_KEYS.deleteAgentCommand):
                    await this.deleteAgentCommandFromList(this.app.configuration.agent_commands, SETTING_NAME_FOR_LIST.AGENT_COMMANDS);
                    break;
                case this.app.configuration.getUiText(UI_TEXT_KEYS.viewAgentCommandDetails):
                    await this.viewAgentCommandFromList(this.app.configuration.agent_commands);
                    break;
                case this.app.configuration.getUiText(UI_TEXT_KEYS.editAgentCommandDetails):
                    await this.editAgentCommandFromList(this.app.configuration.agent_commands);
                    break;
                case this.app.configuration.getUiText(UI_TEXT_KEYS.exportAgentCommand):
                    await this.exportAgentCommandFromList(this.app.configuration.agent_commands);
                    break;
                case this.app.configuration.getUiText(UI_TEXT_KEYS.importAgentCommand):
                    await this.importAgentCommandToList(this.app.configuration.agent_commands, SETTING_NAME_FOR_LIST.AGENT_COMMANDS);
                    break;
                default:
                    vscode.window.showWarningMessage("Unknown action");
            }
        } catch (error) {
            vscode.window.showErrorMessage(`Error processing action: ${error instanceof Error ? error.message : 'Unknown error'}`);
            console.error(error);
        }
    }

    public async addAgentCommand(): Promise<void> {
        this.app.llamaWebviewProvider.addEditAgentCommand({}, null as any)
    }

    private async deleteAgentCommandFromList(agentCommands: AgentCommand[], settingName: string) {
        const modelsItems: QuickPickItem[] = Utils.getStandardQpList(agentCommands, "");
        const model = await vscode.window.showQuickPick(modelsItems);
        if (model) {
            let modelIndex = parseInt(model.label.split(". ")[0], 10) - 1;
            const shoulDeleteModel = await this.app.dialogs.confirmAction("Are you sure you want to delete the agent command below?", 
                this.getAgentCommandDetailsAsString(agentCommands[modelIndex])
            );
            if (shoulDeleteModel) {
                agentCommands.splice(modelIndex, 1);
                this.app.configuration.updateConfigValue(settingName, agentCommands);
                vscode.window.showInformationMessage("The agent command is deleted.")
            }
        }
    }

    private async viewAgentCommandFromList(agentCommands: any[]) {
        let allAgentCommands = agentCommands.concat(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENT_COMMANDS) as AgentCommand[])
        let agentComandItems: QuickPickItem[] = Utils.getStandardQpList(agentCommands, "");
        agentComandItems = agentComandItems.concat(Utils.getStandardQpList(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENT_COMMANDS) as AgentCommand[], "(predefined) ", agentCommands.length));
        let agentCommand = await vscode.window.showQuickPick(agentComandItems);
        if (agentCommand) {
            let agentCommandIndex = parseInt(agentCommand.label.split(". ")[0], 10) - 1;
            let selectedAgentCommand =  allAgentCommands[agentCommandIndex];
            await this.showAgentCommandDetails(selectedAgentCommand);
        }
    }

    public async editAgentCommandFromList(agentCommands: any[]) {
        let allAgentCommands = agentCommands.concat(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENT_COMMANDS) as AgentCommand[])
        let agentComandItems: QuickPickItem[] = Utils.getStandardQpList(agentCommands, "");
        agentComandItems = agentComandItems.concat(Utils.getStandardQpList(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENT_COMMANDS) as AgentCommand[], "(predefined) ", agentCommands.length));
        let agentCommand = await vscode.window.showQuickPick(agentComandItems);
        if (agentCommand) {
            let agentCommandIndex = parseInt(agentCommand.label.split(". ")[0], 10) - 1;
            let selectedAgentCommand =  allAgentCommands[agentCommandIndex] as AgentCommand;
            this.app.llamaWebviewProvider.addEditAgentCommandToUi(selectedAgentCommand)
        }
    }

    public async showAgentCommandDetails(selectedAgentCommand: any) {
        await this.app.dialogs.showOkDialog(
            this.getAgentCommandDetailsAsString(selectedAgentCommand)
        );
    }

    /**
     * Returns a user-defined agent command by name (configuration.agent_commands
     * only - predefined commands are not returned).
     */
    public getAgentCommand(commandName: string): AgentCommand | undefined {
        let commands = this.app.configuration.agent_commands as AgentCommand[]
        commands = commands.concat(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENT_COMMANDS) as AgentCommand[]) as AgentCommand[];
        return (commands).find(cmd => cmd.name === commandName);
    }

    /**
     * Adds a new agent command or updates an existing one (matched by name).
     * Used by the AgentCommandEditor UI.
     */
    public async addUpdateAgentCommand(agentCommand: AgentCommand): Promise<void> {
        const agentCommands = this.app.configuration.agent_commands as AgentCommand[];
        const existing = agentCommands.find(cmd => cmd.name === agentCommand.name);
        if (existing) {
            const shouldUpdate = await this.app.dialogs.confirmAction(
                "Do you want to update the agent command?",
                this.getAgentCommandDetailsAsString(agentCommand)
            );
            if (shouldUpdate) {
                Object.assign(existing, agentCommand);
                this.app.configuration.updateConfigValue(SETTING_NAME_FOR_LIST.AGENT_COMMANDS, agentCommands);
                vscode.window.showInformationMessage("The agent command is updated: " + existing.name);
            }
        } else {
            await this.persistAgentCommandToSetting(agentCommand, agentCommands, SETTING_NAME_FOR_LIST.AGENT_COMMANDS);
        }
    }

    public async copyAgentCommand(): Promise<void> {
        let agentCommandsList = this.app.configuration.agent_commands
        let allAgentCommands = agentCommandsList.concat(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENT_COMMANDS) as Agent[]);
        let agentCommandsItems: QuickPickItem[] = this.getStandardQpList(agentCommandsList, "");
        agentCommandsItems = agentCommandsItems.concat(this.getStandardQpList(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENT_COMMANDS) as AgentCommand[], "(predefined) ", agentCommandsList.length));
        let agentCommandItem = await vscode.window.showQuickPick(agentCommandsItems);
        if (agentCommandItem) {
            this.app.llamaWebviewProvider.showAgentCommandEditorInUi();
            let agentCommandIndex = parseInt(agentCommandItem.label.split(". ")[0], 10) - 1;
            const selectedAgentCommand = allAgentCommands[agentCommandIndex];
            const copyCommand: AgentCommand = {
                ...selectedAgentCommand,
                name: "Copy of " + selectedAgentCommand.name
            };
            this.app.llamaWebviewProvider.addEditAgentCommandToUi(copyCommand)
        }
    }

    private getStandardQpList(list: AgentCommand[], prefix: string, lastAgentCommandNumber: number = 0): QuickPickItem[] {
        const items: QuickPickItem[] = [];
        let i = lastAgentCommandNumber;
        for (let elem of list) {
            i++;
            items.push({
                label: i + ". " + prefix + elem.name,
                description: elem.description,
            });
        }
        return items;
    }

    /**
     * Deletes a user-defined agent command by name.
     */
    public async deleteAgentCommandByName(commandName: string): Promise<boolean> {
        const agentCommands = this.app.configuration.agent_commands as AgentCommand[];
        const index = agentCommands.findIndex(cmd => cmd.name === commandName);
        if (index === -1) {
            vscode.window.showWarningMessage("The agent command to delete is not found!");
            return false;
        }
        const shouldDelete = await this.app.dialogs.confirmAction(
            "Are you sure you want to delete the agent command below?",
            this.getAgentCommandDetailsAsString(agentCommands[index])
        );
        if (shouldDelete) {
            agentCommands.splice(index, 1);
            this.app.configuration.updateConfigValue(SETTING_NAME_FOR_LIST.AGENT_COMMANDS, agentCommands);
            vscode.window.showInformationMessage("The agent command is deleted.");
            return true;
        }
        return false;
    }

    getAgentCommandsList = () => {
        let commands = this.getAgentCommands();

        let agentCommands =  commands.map(cmd => `${cmd.executePeriodically ? "⏰ " : ""}[${cmd.noPrompt?AGENT_COMMAND.type_preffix_script:AGENT_COMMAND.type_preffix_prompt}]${cmd.name} | ${cmd.description}`)

        const scriptsFolder = path.join(this.app.configuration.scripts_folder, "")
        let scriptCommands = this.getScriptCommands()
        scriptCommands = scriptCommands.map(dirent => `[${AGENT_COMMAND.type_preffix_script}]${dirent}`)

        agentCommands = agentCommands.concat(scriptCommands)

        return agentCommands;
    }

    getAgentCmdsListForTelegram = () => {
        let commands = this.getAgentCommands();

        let agentCommands =  commands.map(cmd => `/${cmd.name} [${cmd.noPrompt?AGENT_COMMAND.type_preffix_script:AGENT_COMMAND.type_preffix_prompt}] | ${cmd.description}`)

        let scriptCommands = this.getScriptCommands();
        scriptCommands = scriptCommands.map(cmd => `/${cmd} [${AGENT_COMMAND.type_preffix_script}]`)
        agentCommands = agentCommands.concat(scriptCommands)

        return agentCommands;
    }

    isAgentCommand = (cmdToFind: string): boolean => {
        let isCommand = false;
        cmdToFind = cmdToFind.trim();
        if (this.getAgentCommands().find(cmd => cmd.name == cmdToFind)
            ||this.getScriptCommands().find(cmd => cmd == cmdToFind)){
            isCommand = true
        }

        return isCommand
    }

    private getScriptCommands(): string[] {
        let scriptCommands:string[] = []
        const scriptsFolder = path.join(this.app.configuration.scripts_folder, "");
        if (fs.existsSync(scriptsFolder)){
            scriptCommands = fs.readdirSync(scriptsFolder, { withFileTypes: true }).filter(dirent => dirent.isFile() && dirent.name.toLowerCase().endsWith(".lvs")).map(file => file.name);
        }
        return scriptCommands;
    }

    private getAgentCommands() {
        let commands = this.app.configuration.agent_commands as AgentCommand[];
        commands = commands.concat(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENT_COMMANDS) as AgentCommand[]) as AgentCommand[];

        if (this.app.configuration.enabled) commands = commands.filter(cmd => cmd.name != "enable_completions");
        else commands = commands.filter(cmd => cmd.name != "disable_completions");

        if (this.app.configuration.rag_enabled) commands = commands.filter(cmd => cmd.name != "enable_rag");
        else commands = commands.filter(cmd => cmd.name != "disable_rag");
        return commands;
    }

    private async persistAgentCommandToSetting(newAgentCommand: AgentCommand, agentCommands: any[], settingName: string) {
        let modelDetails = this.getAgentCommandDetailsAsString(newAgentCommand);
        const shouldAddModel = await this.app.dialogs.confirmAction("A new agent command will be added. Do you want to add the agent command?", modelDetails);

        if (shouldAddModel) {
            agentCommands.push(newAgentCommand);
            this.app.configuration.updateConfigValue(settingName, agentCommands);
            vscode.window.showInformationMessage("The agent command is added.");
        }
    }

    private async exportAgentCommandFromList(agentCommands: any[]) {
        let allAgentCommands = agentCommands.concat(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENT_COMMANDS) as Agent[])
        let agentComandItems: QuickPickItem[] = Utils.getStandardQpList(agentCommands, "");
        agentComandItems = agentComandItems.concat(Utils.getStandardQpList(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENT_COMMANDS) as Agent[], "(predefined) ", agentCommands.length));
        let agentCommand = await vscode.window.showQuickPick(agentComandItems);
        if (agentCommand) {
            let modelIndex = parseInt(agentCommand.label.split(". ")[0], 10) - 1;
            let selectedAgentCommand =  allAgentCommands[modelIndex];
            let shouldExport = await this.app.dialogs.showYesNoDialog("Do you want to export the following agent command? \n\n" +
            this.getAgentCommandDetailsAsString(selectedAgentCommand)
            );

            if (shouldExport){
                const uri = await vscode.window.showSaveDialog({
                        defaultUri: vscode.Uri.file(path.join(vscode.workspace.rootPath || '', selectedAgentCommand.name+'.json')),
                        filters: {
                            'Agent Command Files': ['json'],
                            'All Files': ['*']
                        },
                        saveLabel: 'Export Agent Command'
                    });

                if (!uri) {
                    return;
                }

                const jsonContent = JSON.stringify(selectedAgentCommand, null, 2);
                fs.writeFileSync(uri.fsPath, jsonContent, 'utf8');
                vscode.window.showInformationMessage("Agent command is saved.")
            }
        }
    }

    private async importAgentCommandToList(agentCommands: any[], settingName: string) {
        let name = "";
        const uris = await vscode.window.showOpenDialog({
                canSelectMany: false,
                openLabel: 'Import Agent Command',
                filters: {
                    'Agent Command Files': ['json'],
                    'All Files': ['*']
                },
            });

        if (!uris || uris.length === 0) {
            return;
        }

        const filePath = uris[0].fsPath;

        const fileContent = fs.readFileSync(filePath, 'utf8');
        const newAgentCommand = JSON.parse(fileContent);
        // Sanitize imported agent command
        if (newAgentCommand.name) newAgentCommand.name = this.app.modelService.sanitizeInput(newAgentCommand.name);
        if (newAgentCommand.description) newAgentCommand.description = this.app.modelService.sanitizeInput(newAgentCommand.description);
        if (newAgentCommand.prompt) newAgentCommand.prompt = newAgentCommand.prompt.map((s: string) => this.app.modelService.sanitizeInput(s));
        if (newAgentCommand.context) newAgentCommand.context = newAgentCommand.context.map((s: string) => this.app.modelService.sanitizeInput(s));
        if (newAgentCommand.startTime) newAgentCommand.startTime = this.app.modelService.sanitizeInput(newAgentCommand.startTime);
        // Numeric / boolean scheduling fields are used as-is but coerced to the
        // expected types so a malformed import cannot break the scheduler.
        newAgentCommand.executePeriodically = Boolean(newAgentCommand.executePeriodically);
        newAgentCommand.period = newAgentCommand.period !== undefined && newAgentCommand.period !== null ? Number(newAgentCommand.period) : undefined;
        newAgentCommand.totalExecutionTimes = newAgentCommand.totalExecutionTimes !== undefined && newAgentCommand.totalExecutionTimes !== null ? Number(newAgentCommand.totalExecutionTimes) : undefined;

        await this.persistAgentCommandToSetting(newAgentCommand, agentCommands, settingName);
    }

     private getAgentCommandDetailsAsString(selectedAgentCommand: AgentCommand): string {
        return "Agent command details: " +
            "\nname: " + selectedAgentCommand.name +
            "\ndescription: " + selectedAgentCommand.description +
            "\nprompt: \n" + selectedAgentCommand.prompt.join("\n") +
            "\nis script: " + selectedAgentCommand.isScript +
            "\nno prompt to the agent: " + selectedAgentCommand.noPrompt +
            "\n\nexecute periodically: " + selectedAgentCommand.executePeriodically +
            "\nstart time: " + selectedAgentCommand.startTime +
            "\nperiod (seconds): " + selectedAgentCommand.period +
            "\ntotal execution times: " + (selectedAgentCommand.totalExecutionTimes || "infinite") +
            "\n\ncontext: " + (selectedAgentCommand.context ? selectedAgentCommand.context.join(", ") : "");
    }
}

import * as vscode from "vscode";
import { QuickPickItem } from "vscode";
import { Application } from "../application";
import { Agent } from "../types";
import { Utils } from "../utils";
import * as fs from "fs";
import * as path from "path";
import { PREDEFINED_LISTS } from "../lists";
import { UI_TEXT_KEYS, PERSISTENCE_KEYS, SETTING_NAME_FOR_LIST, PREDEFINED_LISTS_KEYS, ModelType } from "../constants";

export class AgentService {
    private app: Application;
    public editedAgentTools: Map<string,string> = new Map();

    constructor(app: Application) {
        this.app = app;
    }

    getActions(): vscode.QuickPickItem[] {
        return [
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.selectStartAgent) ?? ""
            },
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.deselectStopAgent) ?? ""
            },
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.addAgent) ?? "",
            },
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.editAgent) ?? "",
            },
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.copyAgent) ?? "",
            },
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.viewAgentDetails) ?? ""
            },
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.deleteAgent) ?? ""
            },
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.exportAgent) ?? ""
            },
            {
                label: this.app.configuration.getUiText(UI_TEXT_KEYS.importAgent) ?? ""
            },
        ];
    }

    async processActions(): Promise<void> {
        let agentsActions: vscode.QuickPickItem[] = this.app.agentService.getActions();
        let actionSelected = await vscode.window.showQuickPick(agentsActions);
        if (!actionSelected) return
        switch (actionSelected.label) {
            case this.app.configuration.getUiText(UI_TEXT_KEYS.selectStartAgent):
                await this.pickAndSelectAgent(this.app.configuration.agents_list);
                break;
            case this.app.configuration.getUiText(UI_TEXT_KEYS.addAgent):
                await this.addAgent(this.app.configuration.agents_list, SETTING_NAME_FOR_LIST.AGENTS);
                break;
            case this.app.configuration.getUiText(UI_TEXT_KEYS.editAgent):
                this.editAgent(this.app.configuration.agents_list);
                break;
            case this.app.configuration.getUiText(UI_TEXT_KEYS.copyAgent):
                this.copyAgent();
                break;
            case this.app.configuration.getUiText(UI_TEXT_KEYS.deleteAgent):
                await this.deleteAgent();
                break;
            case this.app.configuration.getUiText(UI_TEXT_KEYS.viewAgentDetails):
                await this.viewAgent(this.app.configuration.agents_list);
                break;
            case this.app.configuration.getUiText(UI_TEXT_KEYS.deselectStopAgent):
                await this.deselectAgent();
                break;
            case this.app.configuration.getUiText(UI_TEXT_KEYS.exportAgent):
                await this.exportAgent(this.app.configuration.agents_list);
                break;
            case this.app.configuration.getUiText(UI_TEXT_KEYS.importAgent):
                await this.importAgent(this.app.configuration.agents_list, SETTING_NAME_FOR_LIST.AGENTS);
                break;
        }
    }

    public async pickAndSelectAgent(agentsList: Agent[]): Promise<Agent | undefined> {
        let allAgents = agentsList.concat(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENTS) as Agent[]);
        let agentsItems: QuickPickItem[] = this.getStandardQpList(agentsList, "");
        agentsItems = agentsItems.concat(this.getStandardQpList(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENTS) as Agent[], "(predefined) ", agentsList.length));
        let lastUsedAgent = this.app.persistence.getValue(PERSISTENCE_KEYS.SELECTED_AGENT) as Agent;
        if (lastUsedAgent && lastUsedAgent.name.trim() !== "") {
            agentsItems.push({ label: (agentsItems.length + 1) + ". Last used agent", description: lastUsedAgent.name });
        }
        const agentItem = await vscode.window.showQuickPick(agentsItems);
        if (agentItem) {
            let selectedAgent: Agent;
            if (agentItem.label.includes("Last used agent")) {
                selectedAgent = lastUsedAgent;
            } else {
                const index = parseInt(agentItem.label.split(". ")[0], 10) - 1;
                selectedAgent = allAgents[index];
            }
            if (selectedAgent) {
                await this.selectAgent(selectedAgent);
                vscode.window.showInformationMessage(`Agent is selected:  ${selectedAgent.name}`);
                return selectedAgent;
            }
        }
        return undefined;
    }

    async selectAgent(agent: Agent, showInfo: boolean = true): Promise<void> {
        this.app.setAgent(agent);
        const allTools = Array.from(this.app.tools.toolsFunc.keys());
        for (let toolName of allTools) {
            try {
                await this.app.configuration.updateConfigValue(`tool_${toolName}_enabled`, agent.tools?.includes(toolName) ?? false);
            } catch (err) {
                vscode.window.showErrorMessage("Error updating tools configuration.")
            }
        }
        if (agent.toolsModel && agent.toolsModel.name) {
            await this.app.modelService.selectStartModel(agent.toolsModel, ModelType.Tools, this.app.modelService.getTypeDetails(ModelType.Tools))
        }
        await this.app.persistence.setValue(PERSISTENCE_KEYS.SELECTED_AGENT, agent);
        this.app.llamaWebviewProvider.updateLlamaView();
        if (agent.name.trim() !== "" && showInfo) {
            vscode.window.showInformationMessage(`Agent ${agent.name} is selected.`);
        }
    } 

    async deselectAgent(): Promise<void> {
        const emptyAgent = { name: "", systemInstruction: [] };
        this.app.setAgent(emptyAgent);
        const allTools = Array.from(this.app.tools.toolsFunc.keys());
        for (let toolName of allTools) {
            this.app.configuration.updateConfigValue(`tool_${toolName}_enabled`, true);
        }
        await this.app.persistence.setValue(PERSISTENCE_KEYS.SELECTED_AGENT, emptyAgent);
        this.app.llamaWebviewProvider.updateLlamaView();
        vscode.window.showInformationMessage("The agent is deselected.");
    }

    async addAgent(agentsList: Agent[], settingName: string): Promise<void> {
        this.app.llamaWebviewProvider.showAgentEditorInUi();
        this.app.llamaWebviewProvider.addEditAgnt({name: "", description: "", systemInstruction: [], tools: []})
    }

    selectTools = async (currentTools: string[]): Promise<string[]> => {
        const availableTools = Array.from(this.app.tools.toolsFunc.keys()).map(tool => ({
            label: tool,
            picked: currentTools.includes(tool)
        }));
        const selectedToolsItems = await vscode.window.showQuickPick(availableTools, {
            canPickMany: true,
            placeHolder: 'Select tools for the agent'
        });
        const tools = selectedToolsItems ? selectedToolsItems.map(item => item.label) : currentTools;

        return tools;
    }

    private async persistNewAgent(newAgent: Agent, agentsList: Agent[], settingName: string, confirmMessage: string): Promise<void> {
        let agentDetails = this.getAgentDetailsAsString(newAgent);
        const shouldAddAgent = await this.app.dialogs.confirmAction(confirmMessage, agentDetails);

        if (shouldAddAgent) {
            agentsList.push(newAgent);
            this.app.configuration.updateConfigValue(settingName, agentsList);
            vscode.window.showInformationMessage("The agent is added.");
        }
    }

    private async persistEditedAgent(editedAgent: Agent, agentsList: Agent[], settingName: string): Promise<void> {
        let agentDetails = this.getAgentDetailsAsString(editedAgent);
        const shouldAddAgent = await this.app.dialogs.confirmAction("Do you want to update agent?", agentDetails);

        if (shouldAddAgent) {
            let agentExisting = agentsList.find(agn => agn.name.trim() == editedAgent.name.trim())
            if (agentExisting){
                agentExisting.description = editedAgent.description
                agentExisting.subagentEnabled = editedAgent.subagentEnabled
                agentExisting.systemInstruction = editedAgent.systemInstruction
                agentExisting.toolsModel = editedAgent.toolsModel
                agentExisting.tools = editedAgent.tools
                this.app.configuration.updateConfigValue(settingName, agentsList);
                vscode.window.showInformationMessage("The agent is updated: " + agentExisting.name);
            } else {
                vscode.window.showWarningMessage("The agent to update is not found!")
            }
        }
    }

    addUpdateAgent = async (agentToAddUpdate: Agent) => {
        let agentsList = this.app.configuration.agents_list;
        if (agentsList.findIndex(agn => agn.name.trim() == agentToAddUpdate.name.trim()) == -1){
            await this.persistNewAgent(
                agentToAddUpdate, 
                agentsList, 
                SETTING_NAME_FOR_LIST.AGENTS,
                "A new agent will be added. Do you want to add the agent?"
            );
        } else {
            await this.persistEditedAgent(agentToAddUpdate, agentsList, SETTING_NAME_FOR_LIST.AGENTS)
        }
    }

    async deleteAgent(): Promise<void> {
        let agentsList: Agent[] = this.app.configuration.agents_list;
        const agentsItems: QuickPickItem[] = this.getStandardQpList(agentsList, "");
        const agentItem = await vscode.window.showQuickPick(agentsItems);
        if (agentItem) {
            let agentIndex = parseInt(agentItem.label.split(". ")[0], 10) - 1;
            const shouldDeleteAgent = await this.app.dialogs.confirmAction("Are you sure you want to delete the following agent?",
                this.getAgentDetailsAsString(agentsList[agentIndex])
            );
            if (shouldDeleteAgent) {
                agentsList.splice(agentIndex, 1);
                this.app.configuration.updateConfigValue(SETTING_NAME_FOR_LIST.AGENTS, agentsList);
                vscode.window.showInformationMessage("The agent is deleted.")
            }
        }
    }

    async editAgent(agentsList: Agent[]): Promise<void> {
        const agentsItems: QuickPickItem[] = this.getStandardQpList(agentsList, "");
        const agentItem = await vscode.window.showQuickPick(agentsItems);
        if (agentItem) {
            let agentIndex = parseInt(agentItem.label.split(". ")[0], 10) - 1;
            this.app.llamaWebviewProvider.showAgentEditorInUi();
            setTimeout(() => {
                this.app.llamaWebviewProvider.addEditAgnt(agentsList[agentIndex])
            }, 500);

        }
    }

    async copyAgent(): Promise<void> {
        let agentsList = this.app.configuration.agents_list
        let allAgents = agentsList.concat(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENTS) as Agent[]);
        let agentsItems: QuickPickItem[] = this.getStandardQpList(agentsList, "");
        agentsItems = agentsItems.concat(this.getStandardQpList(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENTS) as Agent[], "(predefined) ", agentsList.length));
        let agentItem = await vscode.window.showQuickPick(agentsItems);
        if (agentItem) {
            let agentIndex = parseInt(agentItem.label.split(". ")[0], 10) - 1;
            this.app.llamaWebviewProvider.showAgentEditorInUi();
            const selectedAgent = allAgents[agentIndex];
            const newAgent: Agent = {
                name: "Copy of " + agentItem.label,
                description: selectedAgent.description,
                systemInstruction: selectedAgent.systemInstruction,
                tools: selectedAgent.tools
            }
            setTimeout(() => {
                this.app.llamaWebviewProvider.addEditAgnt(newAgent)
            }, 500);
        }
    }

    async viewAgent(agentsList: Agent[]): Promise<void> {
        let allAgents = agentsList.concat(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENTS) as Agent[]);
        let agentsItems: QuickPickItem[] = this.getStandardQpList(agentsList, "");
        agentsItems = agentsItems.concat(this.getStandardQpList(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENTS) as Agent[], "(predefined) ", agentsList.length));
        let agentItem = await vscode.window.showQuickPick(agentsItems);
        if (agentItem) {
            let agentIndex = parseInt(agentItem.label.split(". ")[0], 10) - 1;
            let selectedAgent = allAgents[agentIndex];
            await this.showAgentDetails(selectedAgent);
        }
    }

    public async showAgentDetails(selectedAgent: Agent) {
        let agentDetails = this.getAgentDetailsAsString(selectedAgent);
        await this.app.dialogs.showOkDialog(agentDetails);
    }

    async exportAgent(agentsList: Agent[]): Promise<void> {
        let allAgents = agentsList.concat(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENTS) as Agent[]);
        let agentsItems: QuickPickItem[] = this.getStandardQpList(agentsList, "");
        agentsItems = agentsItems.concat(this.getStandardQpList(PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENTS) as Agent[], "(predefined) ", agentsList.length));
        let agentItem = await vscode.window.showQuickPick(agentsItems);
        if (agentItem) {
            let agentIndex = parseInt(agentItem.label.split(". ")[0], 10) - 1;
            let selectedAgent = allAgents[agentIndex];
            let shouldExport = await this.app.dialogs.showYesNoDialog("Do you want to export the following agent? \n\n" +
                this.getAgentDetailsAsString(selectedAgent)
            );

            if (shouldExport) {
                const uri = await vscode.window.showSaveDialog({
                    defaultUri: vscode.Uri.file(path.join(vscode.workspace.rootPath || '', selectedAgent.name + '.json')),
                    filters: {
                        'Agent Files': ['json'],
                        'All Files': ['*']
                    },
                    saveLabel: 'Export Agent'
                });

                if (uri) {
                    const jsonContent = JSON.stringify(selectedAgent, null, 2);
                    fs.writeFileSync(uri.fsPath, jsonContent, 'utf8');
                    vscode.window.showInformationMessage("Agent is saved.")
                }
            }
        }
    }

    async importAgent(agentsList: Agent[], settingName: string): Promise<void> {
        const uris = await vscode.window.showOpenDialog({
            canSelectMany: false,
            openLabel: 'Import Agent',
            filters: {
                'Agent Files': ['json'],
                'All Files': ['*']
            },
        });

        if (!uris || uris.length === 0) {
            return;
        }

        const filePath = uris[0].fsPath;
        const fileContent = fs.readFileSync(filePath, 'utf8');
        let newAgent: Agent = JSON.parse(fileContent);

        // Sanitize imported agent
        this.sanitizeAgent(newAgent);

        await this.persistNewAgent(newAgent, agentsList, settingName,"A new agent will be added. Do you want to add the agent?");
    }

    private sanitizeAgent(agent: Agent): void {
        if (agent.name) agent.name = this.app.modelService.sanitizeInput(agent.name);
        if (agent.description) agent.description = this.app.modelService.sanitizeInput(agent.description);
        if (agent.systemInstruction) {
            agent.systemInstruction = agent.systemInstruction.map((s: string) => this.app.modelService.sanitizeInput(s));
        }
        // tools are strings, no need
    }

    public getAgentDetailsAsString(agent: Agent): string {
        return "Agent details: " +
            "\nname: " + agent.name +
            "\ndescription: " + agent.description +
            "\nsystem prompt: \n" + agent.systemInstruction.join("\n") +
            "\nsubagent enabled: " + agent.subagentEnabled +
            "\ntools model: \n" + agent.toolsModel?.name +
            "\n\ntools: " + (agent.tools ? agent.tools.join(", ") : "");
    }

    private getStandardQpList(list: Agent[], prefix: string, lastAgentNumber: number = 0): QuickPickItem[] {
        const items: QuickPickItem[] = [];
        let i = lastAgentNumber;
        for (let elem of list) {
            i++;
            items.push({
                label: i + ". " + prefix + elem.name,
                description: elem.description,
            });
        }
        return items;
    }

    resetEditedAgentTools = () => {
        this.editedAgentTools.clear();
        this.app.llamaWebviewProvider.updateContextFilesInfo();
    }

    addEditedAgentTools = (toolName: string, toolDescription: string) => {
        this.editedAgentTools.set(toolName, toolDescription);
    }

    removeEditedAgentTools = (toolName: string) => {
        this.editedAgentTools.delete(toolName);
    }

    getEditedAgentTools = () => {
        return this.editedAgentTools;
    }

    getAllAgentsList = (): Agent[] => {
        return this.app.configuration.agents_list
                .concat((PREDEFINED_LISTS.get(PREDEFINED_LISTS_KEYS.AGENTS) as Agent[]))
    }
}

import React, { useState, useEffect, useRef } from 'react';
import { vscode } from '../types/vscode';

interface AgentCommandEditDetails {
  name: string;
  description: string;
  prompt: string;
  noPrompt: boolean;
  isScript: boolean;
  executePeriodically: boolean;
  startTime: string;
  period: string;
  totalExecutionTimes: string;
}

const emptyDetails: AgentCommandEditDetails = {
  name: "",
  description: "",
  prompt: "",
  noPrompt: false,
  isScript: false,
  executePeriodically: false,
  startTime: "",
  period: "",
  totalExecutionTimes: ""
};

// Convert a total number of seconds into its Days/Hours/Minutes/Seconds parts.
const secondsToParts = (totalSeconds: number): { days: number; hours: number; minutes: number; seconds: number } => {
  const total = Math.max(0, Math.floor(totalSeconds));
  return {
    days: Math.floor(total / 86400),
    hours: Math.floor((total % 86400) / 3600),
    minutes: Math.floor((total % 3600) / 60),
    seconds: total % 60
  };
};

// Convert Days/Hours/Minutes/Seconds parts into a total number of seconds.
const partsToSeconds = (days: number, hours: number, minutes: number, seconds: number): number => {
  return (Math.max(0, Math.floor(days)) * 86400) +
         (Math.max(0, Math.floor(hours)) * 3600) +
         (Math.max(0, Math.floor(minutes)) * 60) +
         Math.max(0, Math.floor(seconds));
};

// ISO datetime string -> value for an <input type="datetime-local"> (e.g. "2025-01-01T09:00:00").
const isoToLocalInputValue = (iso: string): string => {
  if (!iso) return "";
  const date = new Date(iso);
  if (isNaN(date.getTime())) return "";
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
};

// value from an <input type="datetime-local"> (e.g. "2025-01-01T09:00") -> ISO datetime string.
const localInputValueToIso = (value: string): string => {
  if (!value) return "";
  const date = new Date(value);
  if (isNaN(date.getTime())) return value;
  return date.toISOString();
};

// Parse a user-entered period part value (empty or non-numeric -> 0).
const parsePartValue = (value: string): number => {
  const n = parseInt(value, 10);
  return isNaN(n) ? 0 : Math.max(0, n);
};

// The Days/Hours/Minutes/Seconds input fields used to edit the period.
const PERIOD_PART_FIELDS = [
  { key: 'days', label: 'Days', title: 'Days (24 hours)' },
  { key: 'hours', label: 'Hours', title: 'Hours' },
  { key: 'minutes', label: 'Minutes', title: 'Minutes' },
  { key: 'seconds', label: 'Seconds', title: 'Seconds' }
] as const;

const AgentCommandEditor: React.FC = () => {
  const [agentCommandEditDetails, setAgentCommandEditDetails] = useState<AgentCommandEditDetails>(emptyDetails);
  const [periodParts, setPeriodParts] = useState<{ days: string; hours: string; minutes: string; seconds: string }>({
    days: "",
    hours: "",
    minutes: "",
    seconds: ""
  });

  // Refs
  const elemNameRef = useRef<HTMLTextAreaElement>(null);

  // Auto-focus the name textarea when the component mounts
  useEffect(() => {
    if (elemNameRef.current) {
      elemNameRef.current.focus();
    }
  }, []);

  useEffect(() => {
    // Listen for messages from the extension
    const handleMessage = (event: MessageEvent) => {
      const message = event.data;
      console.log('Received message from extension:', message);
      switch (message.command) {
        case 'loadAgentCommand':
          setAgentCommandEditDetails({
            name: message.name ?? "",
            description: message.description ?? "",
            prompt: message.prompt ?? "",
            noPrompt: Boolean(message.noPrompt),
            isScript: Boolean(message.isScript),
            executePeriodically: Boolean(message.executePeriodically),
            startTime: message.startTime ?? "",
            period: message.period !== undefined && message.period !== null ? String(message.period) : "",
            totalExecutionTimes: message.totalExecutionTimes !== undefined && message.totalExecutionTimes !== null ? String(message.totalExecutionTimes) : ""
          });
          // Sync the Days/Hours/Minutes/Seconds inputs with the loaded period.
          setPeriodParts((() => {
            const loadedPeriod = message.period !== undefined && message.period !== null ? Number(message.period) : 0;
            const loadedTotal = !isNaN(loadedPeriod) && loadedPeriod > 0 ? Math.floor(loadedPeriod) : 0;
            if (loadedTotal <= 0) return { days: "", hours: "", minutes: "", seconds: "" };
            const p = secondsToParts(loadedTotal);
            return { days: String(p.days), hours: String(p.hours), minutes: String(p.minutes), seconds: String(p.seconds) };
          })());
          break;
        default:
          break;
      }
    };

    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, []);

  const updateDetails = (patch: Partial<AgentCommandEditDetails>) => {
    setAgentCommandEditDetails(prev => ({ ...prev, ...patch }));
  };

  const handlePeriodPartChange = (part: keyof typeof periodParts, value: string) => {
    const nextParts = { ...periodParts, [part]: value };
    setPeriodParts(nextParts);
    const total = partsToSeconds(
      parsePartValue(nextParts.days),
      parsePartValue(nextParts.hours),
      parsePartValue(nextParts.minutes),
      parsePartValue(nextParts.seconds)
    );
    updateDetails({ period: total > 0 ? String(total) : "" });
  };

  const totalPeriodSeconds = partsToSeconds(
    parsePartValue(periodParts.days),
    parsePartValue(periodParts.hours),
    parsePartValue(periodParts.minutes),
    parsePartValue(periodParts.seconds)
  );

  const handleSaveAgentCommand = () => {
    vscode.postMessage({
      command: 'saveEditAgentCommand',
      name: agentCommandEditDetails.name,
      description: agentCommandEditDetails.description,
      prompt: agentCommandEditDetails.prompt,
      noPrompt: agentCommandEditDetails.noPrompt,
      isScript: agentCommandEditDetails.isScript,
      executePeriodically: agentCommandEditDetails.executePeriodically,
      startTime: agentCommandEditDetails.startTime,
      period: agentCommandEditDetails.period,
      totalExecutionTimes: agentCommandEditDetails.totalExecutionTimes
    });
  };

  const handleSelectEditAgentCommand = () => {
    vscode.postMessage({
      command: 'selectEditAgentCommand'
    });
  };

  const handleNewAgentCommand = () => {
    setAgentCommandEditDetails(emptyDetails);
    setPeriodParts({ days: "", hours: "", minutes: "", seconds: "" });
    vscode.postMessage({
      command: 'addEditAgentCommand',
      name: "",
      description: "",
      prompt: "",
      noPrompt: false,
      isScript: false,
      executePeriodically: false,
      startTime: "",
      period: "",
      totalExecutionTimes: ""
    });
  };

  const handleCopyAgentCommand = () => {
    vscode.postMessage({
      command: 'copyAsNewAgentCommand',
      commandName: agentCommandEditDetails.name
    });
  };

  const handleDeleteAgentCommand = () => {
    vscode.postMessage({
      command: 'deleteEditAgentCommand',
      commandName: agentCommandEditDetails.name
    });
  };

  return (
    <div style={{ height: '100vh', display: 'flex', flexDirection: 'column' }}>
      <div className="content" style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
        <div className="input-section" style={{ flexShrink: 0 }}>
          <div className="input-container">
            <h1 style={{ margin: '0 0 20px 0', fontSize: '24px', fontWeight: 'bold' }}>Agent Command Editor</h1>
            <div style={{ display: 'flex', gap: '10px', marginBottom: '20px', flexWrap: 'wrap' }}>
              <button
                onClick={handleSelectEditAgentCommand}
                title="Select Agent Command to Edit"
                className="modern-btn secondary"
              >
                Select
              </button>
              <button
                onClick={handleNewAgentCommand}
                title="New Agent Command"
                className="modern-btn secondary"
              >
                New
              </button>
              <button
                onClick={handleCopyAgentCommand}
                title="Copy Existing Agent Command as New"
                className="modern-btn secondary"
              >
                Copy as New
              </button>
              <button
                onClick={handleDeleteAgentCommand}
                title="Select and Delete Existing Agent Command"
                className="modern-btn secondary"
              >
                Delete
              </button>
            </div>

            <span style={{ display: 'block', marginTop: '20px', marginBottom: '10px', fontWeight: 'bold' }}>{'Name (agent command identifier)'}</span>
            <textarea
              ref={elemNameRef}
              value={agentCommandEditDetails.name}
              onChange={(e) => updateDetails({ name: e.target.value })}
              placeholder="Enter agent command name."
              className="modern-textarea"
              rows={1}
              style={{ height: 'auto', minHeight: '1.5em', resize: 'none' }}
            />

            <span style={{ display: 'block', marginTop: '20px', marginBottom: '10px', fontWeight: 'bold' }}>{'Description'}</span>
            <textarea
              value={agentCommandEditDetails.description}
              onChange={(e) => updateDetails({ description: e.target.value })}
              placeholder="Enter agent command description."
              className="modern-textarea"
              rows={2}
              style={{ height: 'auto', minHeight: '3em', resize: 'none' }}
            />

            <span style={{ display: 'block', marginTop: '20px', marginBottom: '10px', fontWeight: 'bold' }}>{'Prompt/Script'}</span>
            <textarea
              value={agentCommandEditDetails.prompt}
              onChange={(e) => updateDetails({ prompt: e.target.value })}
              placeholder="Enter the prompt for the agent."
              className="modern-textarea"
              rows={8}
              style={{ height: 'auto', minHeight: '12em', resize: 'vertical' }}
            />

            <div style={{ marginBottom: '10px', marginTop: '10px' }}>
              <label className="checkbox-label" title="If enabled, the command does not send a prompt to the agent - for example it just sets a model or a setting.">
                <input
                  type="checkbox"
                  checked={agentCommandEditDetails.noPrompt}
                  onChange={(e) => updateDetails({ noPrompt: e.target.checked })}
                />
                <span style={{ marginLeft: '8px' }}>No prompt to the agent</span>
              </label>
            </div>
            <div style={{ marginBottom: '20px' }}>
              <label className="checkbox-label" title="If enabled, the prompt field content is interpreted as a script.">
                <input
                  type="checkbox"
                  checked={agentCommandEditDetails.isScript}
                  onChange={(e) => updateDetails({ isScript: e.target.checked })}
                />
                <span style={{ marginLeft: '8px' }}>Is script</span>
              </label>
            </div>

            <span style={{ display: 'block', marginTop: '20px', marginBottom: '10px', fontWeight: 'bold' }}>{'Periodic Execution'}</span>
            <div style={{ marginBottom: '10px' }}>
              <label className="checkbox-label" title="If enabled, the command is executed periodically by the scheduler in background agent sessions.">
                <input
                  type="checkbox"
                  checked={agentCommandEditDetails.executePeriodically}
                  onChange={(e) => updateDetails({ executePeriodically: e.target.checked })}
                />
                <span style={{ marginLeft: '8px' }}>Execute periodically</span>
              </label>
            </div>
            {agentCommandEditDetails.executePeriodically && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', marginBottom: '20px' }}>
                <div>
                  <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold' }}>
                    Start Time (ISO datetime, optional)
                  </label>
                  <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                    <input
                      type="datetime-local"
                      step="1"
                      value={isoToLocalInputValue(agentCommandEditDetails.startTime)}
                      onChange={(e) => updateDetails({ startTime: localInputValueToIso(e.target.value) })}
                      title="Pick the date/time when the command should first run (empty = start immediately)"
                      className="modern-input"
                      style={{ flex: 1, minWidth: 0 }}
                    />
                    <button
                      type="button"
                      onClick={() => updateDetails({ startTime: "" })}
                      title="Clear start time (start immediately)"
                      className="modern-btn secondary"
                      style={{ padding: '6px 12px', fontSize: '13px', flexShrink: 0, whiteSpace: 'nowrap' }}
                    >
                      Clear
