                          placeholder="0"
                          title={field.title}
                          className="modern-input"
                        />
                        <div style={{ fontSize: '11px', opacity: 0.7, marginTop: '2px', textAlign: 'center' }}>{field.label}</div>
                      </div>
                    ))}
