                    value={agentCommandEditDetails.totalExecutionTimes}
                    onChange={(e) => updateDetails({ totalExecutionTimes: e.target.value })}
                    placeholder="e.g. 10 (empty = infinite)"
                    className="modern-input"
                    style={{ width: '100%', boxSizing: 'border-box' }}
                  />
                </div>
              </div>
            )}

