              <div className="input-buttons">
                <button
                  onClick={handleSaveAgentCommand}
                  className="modern-btn secondary"
                  title="Saves the agent command changes or creates a new agent command if the name does not exist."
                >
                  Save
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

